def insertionDepths(values):
    n = len(values)
    order = sorted(range(n), key=lambda i: values[i])
    prv = [-1] * n
    nxt = [-1] * n
    for k in range(n):
        i = order[k]
        if k > 0:
            prv[i] = order[k - 1]
        if k + 1 < n:
            nxt[i] = order[k + 1]
    pa = [-1] * n
    su = [-1] * n
    for i in range(n - 1, -1, -1):
        p, q = prv[i], nxt[i]
        pa[i], su[i] = p, q
        if p != -1:
            nxt[p] = q
        if q != -1:
            prv[q] = p
    depth = [0] * n
    for i in range(1, n):
        d = -1
        if pa[i] != -1:
            d = depth[pa[i]]
        if su[i] != -1 and depth[su[i]] > d:
            d = depth[su[i]]
        depth[i] = d + 1
    return depth
